-- Hangman word list (English and Spanish) with tags.
-- This is the source of truth for the words the app plays. To change the
-- list, add a new migration; do not edit this one after it has been pushed.
-- The difficulty trigger fills difficulty_value on insert.

create temporary table hangman_seed (locale text, word text, tags text[]) on commit drop;

insert into hangman_seed (locale, word, tags)
select loc.key, e.value ->> 'word',
  array(select jsonb_array_elements_text(e.value -> 'tags'))
