insert into public.hangman_words (word, locale, difficulty_value)
select word, locale, 50 from hangman_seed
on conflict (word, locale) do nothing;

insert into public.hangman_tags (tag, locale)
select distinct t.tag, s.locale
from hangman_seed s, unnest(s.tags) as t(tag)
on conflict (tag, locale) do nothing;

insert into public.hangman_word_tags (word_id, tag_id)
select w.id, tg.id
from hangman_seed s
cross join unnest(s.tags) as t(tag)
join public.hangman_words w on w.word = s.word and w.locale = s.locale
join public.hangman_tags tg on tg.tag = t.tag and tg.locale = s.locale
on conflict do nothing;
